import{_ as l,o as i,c as e,ag as t}from"./chunks/framework.-Wrcbzkw.js";const u=JSON.parse('{"title":"D2C 代码生成 Agent 设计","description":"","frontmatter":{},"headers":[],"relativePath":"project/D2C/代码生成Agent设计.md","filePath":"project/D2C/代码生成Agent设计.md","lastUpdated":1781078576000}'),n={name:"project/D2C/代码生成Agent设计.md"};function r(o,a,s,p,h,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="d2c-代码生成-agent-设计" tabindex="-1">D2C 代码生成 Agent 设计 <a class="header-anchor" href="#d2c-代码生成-agent-设计" aria-label="Permalink to &quot;D2C 代码生成 Agent 设计&quot;">​</a></h1><p>代码生成 Agent 是 D2C 流水线的第四个阶段。它接收组件 DSL 和知识检索结果，将结构化设计信息组织为可运行、可维护的前端代码。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>组件 DSL + 项目知识 -&gt; 代码生成 Agent -&gt; React / Vue / HTML</span></span></code></pre></div><h2 id="一、为什么代码生成适合使用大模型" tabindex="-1">一、为什么代码生成适合使用大模型 <a class="header-anchor" href="#一、为什么代码生成适合使用大模型" aria-label="Permalink to &quot;一、为什么代码生成适合使用大模型&quot;">​</a></h2><p>前面的数据清洗和结构转换存在明确规则，而代码生成需要同时处理更多开放问题：</p><ul><li>根据组件语义选择合适的标签和组件</li><li>组织页面、组件和状态代码</li><li>根据上下文生成变量名和事件处理函数</li><li>应用组件库 API 和项目规范</li><li>在视觉还原与代码可维护性之间取得平衡</li></ul><p>这些任务很难通过固定模板覆盖所有情况，却适合大模型根据上下文进行组合和生成。</p><h2 id="二、为什么不能直接从-figma-生成代码" tabindex="-1">二、为什么不能直接从 Figma 生成代码 <a class="header-anchor" href="#二、为什么不能直接从-figma-生成代码" aria-label="Permalink to &quot;二、为什么不能直接从 Figma 生成代码&quot;">​</a></h2><p>如果代码生成 Agent直接接收原始 Figma JSON，它还需要完成清洗、结构理解、组件识别和资料查询，任务范围过大。</p><p>经过前置 Agent 后，输入已经变成：</p><ul><li>精简、稳定的组件 DSL</li><li>明确的页面层级</li><li>标准化的布局和样式</li><li>项目组件库文档与规范</li></ul><p>代码生成 Agent 可以集中处理“如何写出高质量代码”，而不是重复解决数据解析问题。</p><h2 id="三、代码生成-agent-的设计目标" tabindex="-1">三、代码生成 Agent 的设计目标 <a class="header-anchor" href="#三、代码生成-agent-的设计目标" aria-label="Permalink to &quot;三、代码生成 Agent 的设计目标&quot;">​</a></h2><ol><li>严格按照 DSL 还原页面结构</li><li>优先使用检索到的项目组件</li><li>生成目标框架要求的完整代码</li><li>遵守导入、命名、样式和目录规范</li><li>尽量减少无意义的绝对定位和重复代码</li><li>输出可供测试验证 Agent 检查的结果</li></ol><h2 id="四、为什么需要约束模型输出" tabindex="-1">四、为什么需要约束模型输出 <a class="header-anchor" href="#四、为什么需要约束模型输出" aria-label="Permalink to &quot;四、为什么需要约束模型输出&quot;">​</a></h2><p>大模型具有创造性，但代码生成阶段需要可控。提示词和输出协议应明确规定：</p><ul><li>目标框架和语言</li><li>可使用的依赖</li><li>组件导入路径</li><li>输出文件结构</li><li>是否允许添加模拟数据</li><li>禁止编造不存在的组件 API</li><li>必须遵循 DSL 的节点层级</li></ul><p>必要时可以要求模型输出结构化结果，例如文件名、代码内容和依赖列表。</p><h2 id="五、为什么单独设计代码生成阶段" tabindex="-1">五、为什么单独设计代码生成阶段 <a class="header-anchor" href="#五、为什么单独设计代码生成阶段" aria-label="Permalink to &quot;五、为什么单独设计代码生成阶段&quot;">​</a></h2><p>独立代码生成 Agent 便于：</p><ul><li>替换或对比不同大模型</li><li>针对 React、Vue 使用不同提示词</li><li>单独记录 Token、延迟和生成质量</li><li>在失败时重新生成，而不重复执行前面步骤</li><li>对生成结果进行专门测试和修复</li></ul><h2 id="六、失败风险与验证方式" tabindex="-1">六、失败风险与验证方式 <a class="header-anchor" href="#六、失败风险与验证方式" aria-label="Permalink to &quot;六、失败风险与验证方式&quot;">​</a></h2><p>常见失败包括：</p><ul><li>编造不存在的组件或属性</li><li>遗漏导入和类型定义</li><li>页面结构与 DSL 不一致</li><li>样式视觉还原不足</li><li>生成重复、难维护的代码</li><li>为了视觉效果过度使用绝对定位</li></ul><p>可以通过编译检查、Lint、组件 API 校验、视觉对比和人工代码审查评估生成质量。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>代码生成 Agent 是将结构化设计真正落地为前端代码的阶段。它利用大模型处理开放的代码组织问题，同时依赖前置 Agent 提供清晰结构和项目知识，从而减少幻觉并提高代码可用性。</p>',27)])])}const g=l(n,[["render",r]]);export{u as __pageData,g as default};
